'use strict';
// Phông chữ nhúng (giấy phép SIL OFL 1.1 — được nhúng/phân phối kèm game):
//  V18Serif = Noto Serif CJK SC Bold (tiêu đề + chữ Hán trang trí), V45Sans = Lora 400/700/italic (chữ thân).
// Đã cắt còn ~550 ký tự (Latin + tiếng Việt + ký hiệu dùng trong game + ~90 chữ Hán trang trí). Tạo lại: tools/build_fonts.py.
const FONT_DATA={title:"",b400:"",b700:"",b400i:""};
(function(){
 if(typeof FontFace==='undefined'||!document.fonts)return;
 const add=(fam,key,desc)=>{const f=new FontFace(fam,'url(data:font/woff;base64,'+FONT_DATA[key]+')',desc);document.fonts.add(f);f.load().catch(e=>console.warn('Phông',fam,e));};
 add('V18Serif','title',{weight:'100 900'});
 add('V45Sans','b400',{weight:'400'});add('V45Sans','b700',{weight:'700'});add('V45Sans','b400i',{weight:'400',style:'italic'});
})();
